  CH.say('Briefing: mortars first, riflemen across, then the dump. Hold '+campClock(c.HOLD)+' once the east end is ours.','g');}

script_js.tick:
tick(c,dt){const d=c.mul,farN=CH.near(0,c.far[0],c.far[1],300),foeFar=CH.near(1,c.far[0],c.far[1],330),tur=G.ents.filter(e=>e.team===1&&e.kind==='turret'&&!e.dead&&Math.hypot(e.x-c.far[0],e.y-c.far[1])<500).length;
  if(!c.o.cross&&farN>=4&&foeFar<=Math.round(2*d)&&tur===0){c.o.cross=true;c.hs=c.t;c.nextWave=c.t+35;CH.flash('The east end of the bridge is ours! Hold it - the enemy will counter-attack along the causeway.','g');CH.radio('Brigade commander','Ya shabab, el-jisir saar ilna','Lads, the bridge is ours','g');G.teams[0].credits+=800;const b=c.near,u=CH.units(0,'inf',8,b[0],b[1],80);CH.go(0,u,c.far[0],c.far[1],true);}
  if(!c.o.dump&&c.depot.owner===0){c.o.dump=true;CH.flash('The ammunition dump is ours: guns on this bank are supplied.','g');}
  if(c.o.cross&&c.t>=c.nextWave){c.wave++;c.nextWave+=Math.round(62/Math.max(.75,d));const k=c.wave,s=CH.pt(.86,0);let us=[...CH.units(1,'inf',(5+k*1.5)*d,s[0],s[1],100),...CH.units(1,'at',(1+k*.4)*d,s[0],s[1],70)];if(k>=2)us.push(...CH.units(1,'tank',(k-.5)*.7*d,s[0],s[1],80));if(k>=4)us.push(...CH.units(1,'arty',d>1?2:1,s[0],s[1],70));
   CH.go(1,us,c.far[0],c.far[1],true);CH.flash('Counter-attack '+k+' is coming down the east causeway.','w');if(k===1)CH.radio('Lookout','Intabihu - el-aduw jaay min el-qasab','Watch out - the enemy comes through the reeds','w');}
  const held=c.o.cross&&c.o.dump;let hold=0;if(c.o.cross){hold=c.hold!=null?c.hold:0;if(held)hold=Math.min(c.HOLD,hold+dt);c.hold=hold;}
  if(c.o.cross&&!c.o.dump&&c.t-c.hs>240&&!c.nag){c.nag=1;CH.flash('The ammunition dump is still in enemy hands. Capture it: infantry stand next to it for a few seconds.','w');}
  if(held&&hold>=c.HOLD&&!c.o.hold){c.o.hold=true;CH.flash('The engineers report: the main column is across.','g');}
  c.status=!c.o.cross?'East end: '+foeFar+' enemy near · '+tur+' emplacements':(held?(c.o.hold?null:'Hold the bridgehead · '+campClock(c.HOLD-hold)):'Capture the dump · hold clock waits');
  if(c.o.cross&&held&&c.o.hold)c.win();
  else if(c.o.cross&&c.t-c.hs>40&&CH.near(0,c.far[0],c.far[1],420)===0&&!c.o.hold)c.lose('The bridgehead was overrun.');
  else if(CH.combat(0)===0&&G.teams[0].credits<250)c.lose('The brigades are spent.');
  else if(!CH.blds(0).some(b=>b.kind==='hq')&&CH.combat(0)===0)c.lose('Base and brigades lost.');}
